policies.inbound:




















  @("{{adi-endpoint}}/documentintelligence/documentModels/prebuilt-layout/analyzeResults/" + (string)context.Variables["jobId"] + "?api-version=2024-11-30")
  GET








<set-variable name="adiBody" value="@(((IResponse)context.Variables["adiResp"]).Body.As())" />








      5
      application/json
      @(new JObject(new JProperty("jobId", (string)context.Variables["jobId"]), new JProperty("status", (string)context.Variables["adiStatus"])).ToString())





<set-variable name="piiRequest" value="@{
    var content = (string)((JObject)context.Variables["adiBody"])["analyzeResult"]["content"] ?? "";
    const int size = 5000;
    var docs = new JArray();
    int i = 0, n = 0;
    while (i < content.Length) {
        int end = Math.Min(i + size, content.Length);
        if (end < content.Length) {
            int ws = content.LastIndexOfAny(new[] { ' ', '\n', '\t' }, end - 1, end - i);
            if (ws > i) { end = ws + 1; }
        }
        docs.Add(new JObject(
            new JProperty("id", n.ToString()),
            new JProperty("language", "en"),
            new JProperty("text", content.Substring(i, end - i))));
        i = end; n++;
    }
    return new JObject(
        new JProperty("kind", "PiiEntityRecognition"),
        new JProperty("parameters", new JObject(
new JProperty("modelVersion", "latest"),
new JProperty("piiCategories", new JArray(
    "Person", "Email", "PhoneNumber", "Address", "USSocialSecurityNumber",
    "USDriversLicenseNumber", "USBankAccountNumber", "IPAddress", "Age",
    "CreditCardNumber", "InternationalBankingAccountNumber", "ABARoutingNumber")))),
        new JProperty("analysisInput", new JObject(new JProperty("documents", docs)))
    ).ToString();
}" />





      application/json
      @(new JObject(new JProperty("jobId", (string)context.Variables["jobId"]), new JProperty("status", "completed"), new JProperty("content", "")).ToString())









  {{language-endpoint}}/language/:analyze-text?api-version=2024-11-01
  POST
  application/json
  @((string)context.Variables["piiRequest"])








<set-variable name="piiDocs" value="@((JArray)((IResponse)context.Variables["piiResp"]).Body.As()["results"]["documents"])" />








      application/json
      @(new JObject(new JProperty("jobId", (string)context.Variables["jobId"]), new JProperty("status", "blocked"), new JProperty("reason", "Payment card data detected")).ToString())






      application/json
      @{
          var docs = ((JArray)context.Variables["piiDocs"]).OrderBy(d => int.Parse((string)d["id"]));
          var cats = docs.SelectMany(d => d["entities"]).Select(e => (string)e["category"]).Distinct().ToArray();
          return new JObject(
              new JProperty("jobId", (string)context.Variables["jobId"]),
              new JProperty("status", "completed"),
              new JProperty("piiRedacted", cats.Length > 0),
              new JProperty("piiCategories", new JArray(cats)),
              new JProperty("content", string.Concat(docs.Select(d => (string)d["redactedText"])))
          ).ToString();
      }
